import os, json, logging, boto3
from botocore.exceptions import ClientError

dynamodb = boto3.resource('dynamodb')
table = dynamodb.Table(os.environ['TABLE_NAME'])
logger = logging.getLogger()
logger.setLevel(logging.INFO)

def lambda_handler(event, context):
    try:
        task_id = event.get('pathParameters', {}).get('id')
        if not task_id:
            return {
                'statusCode': 400,
                'headers': {'Content-Type': 'application/json'},
                'body': json.dumps({'error': 'Missing task ID'})
            }
        body = json.loads(event.get('body', '{}'))
        update_expressions = []
        expression_attribute_values = {}
        for key in ['title', 'description', 'status']:
            if key in body:
                update_expressions.append(f"{key} = :{key}")
                expression_attribute_values[f":{key}"] = body[key]
        if not update_expressions:
            return {
                'statusCode': 400,
                'headers': {'Content-Type': 'application/json'},
                'body': json.dumps({'error': 'No fields to update'})
            }
        update_expression = "SET " + ", ".join(update_expressions)
        table.update_item(
            Key={'task_id': task_id},
            UpdateExpression=update_expression,
            ExpressionAttributeValues=expression_attribute_values
        )
        return {
            'statusCode': 200,
            'headers': {'Content-Type': 'application/json'},
            'body': json.dumps({'message': 'Task updated'})
        }
    except (json.JSONDecodeError, TypeError) as e:
        logger.error(f'Invalid input: {e}')
        return {
            'statusCode': 400,
            'headers': {'Content-Type': 'application/json'},
            'body': json.dumps({'error': 'Invalid request body'})
        }
    except ClientError as e:
        logger.error(f'DynamoDB error: {e}')
        return {
            'statusCode': 500,
            'headers': {'Content-Type': 'application/json'},
            'body': json.dumps({'error': 'Internal server error'})
        }

